/// Generated by capgen from wire.cap: whether one Blob fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_blob(value: &Blob) -> bool {
    value.data.len() <= crate::BYTES_MAX
        && value.parts.len() <= crate::LIST_ITEMS_MAX
        && value
            .tail
            .as_ref()
            .is_none_or(|item0| item0.len() <= crate::BYTES_MAX)
}

/// Generated by capgen from wire.cap: whether one Plain fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_plain(value: &Plain) -> bool {
    value.name.len() <= crate::TEXT_BYTES_MAX
}

